ALTER TABLE contents ADD COLUMN file_id TEXT REFERENCES files(id) ON DELETE RESTRICT;
UPDATE contents SET file_id=json_extract(data,'$.fileId') WHERE EXISTS(SELECT 1 FROM files WHERE id=json_extract(contents.data,'$.fileId'));
CREATE INDEX contents_files ON contents(file_id);
ALTER TABLE files ADD COLUMN media TEXT;
CREATE TABLE oauth_states(state_hash TEXT PRIMARY KEY, cookie_hash TEXT NOT NULL, account_id TEXT NOT NULL REFERENCES accounts(id) ON DELETE CASCADE, session_hash TEXT NOT NULL, expires_at INTEGER NOT NULL);
CREATE TABLE oauth_connections(account_id TEXT PRIMARY KEY REFERENCES accounts(id) ON DELETE CASCADE, open_id TEXT NOT NULL UNIQUE, encrypted_tokens TEXT NOT NULL, scopes TEXT NOT NULL, expires_at INTEGER NOT NULL, nickname TEXT, avatar_url TEXT, refresh_lock TEXT, refresh_lock_until INTEGER NOT NULL DEFAULT 0);
CREATE TABLE publish_jobs(id TEXT PRIMARY KEY, content_id TEXT NOT NULL UNIQUE REFERENCES contents(id) ON DELETE CASCADE, account_id TEXT NOT NULL REFERENCES accounts(id), status TEXT NOT NULL, attempts INTEGER NOT NULL DEFAULT 0, next_at INTEGER NOT NULL, publish_id TEXT, encrypted_upload TEXT, last_error TEXT, lease TEXT, lease_until INTEGER NOT NULL DEFAULT 0, created_at TEXT NOT NULL, updated_at TEXT NOT NULL);
CREATE INDEX publish_due ON publish_jobs(status,next_at);
ALTER TABLE competitors ADD COLUMN last_checked TEXT;
ALTER TABLE competitors ADD COLUMN last_error TEXT;
CREATE TABLE research_videos(id TEXT PRIMARY KEY, competitor_id TEXT NOT NULL REFERENCES competitors(id) ON DELETE CASCADE, data TEXT NOT NULL, fetched_at TEXT NOT NULL);
CREATE INDEX research_dates ON research_videos(fetched_at);
CREATE TABLE trends(id TEXT PRIMARY KEY,title TEXT NOT NULL, source TEXT NOT NULL, data TEXT NOT NULL, fetched_at TEXT NOT NULL);
CREATE TABLE research_reports(id TEXT PRIMARY KEY, data TEXT NOT NULL, created_at TEXT NOT NULL);
CREATE TABLE analytics_history(id TEXT PRIMARY KEY,content_id TEXT NOT NULL REFERENCES contents(id) ON DELETE CASCADE, views INTEGER NOT NULL,likes INTEGER NOT NULL, recorded_at TEXT NOT NULL);
CREATE INDEX analytics_dates ON analytics_history(recorded_at);
CREATE TABLE recommendations(account_id TEXT PRIMARY KEY REFERENCES accounts(id) ON DELETE CASCADE,data TEXT NOT NULL,created_at TEXT NOT NULL);
CREATE TABLE notification_jobs(id TEXT PRIMARY KEY,message TEXT NOT NULL,status TEXT NOT NULL DEFAULT 'ready', attempts INTEGER NOT NULL DEFAULT 0,next_at INTEGER NOT NULL,created_at TEXT NOT NULL);
ALTER TABLE competitors ADD COLUMN cursor TEXT;
ALTER TABLE competitors ADD COLUMN last_attempt_at TEXT;
